'use strict';

const { spell, D, save, buff, damage, condition, inflict, perLevel, cap, mod } = require('./helpers');

/** Core Rulebook spells of levels 4-9 not defined in mid.js / high.js. */

const U = (name, school, levels, description, meta = {}, effect) => spell(name, school, levels, { description, ...meta }, effect);
const sna = (n, lvl, levels) => spell(`Summon Nature's Ally ${n}`, 'conjuration', levels, { subschool: 'summoning', castingTime: '1 round', range: 'close', duration: '1 round/level', sr: false, description: `Summons a creature from the Summon Nature's Ally ${n} list.` }, { kind: 'summon', table: lvl, tables: 'nature' });
const massAbility = (name, ability, levels) => spell(`Mass ${name}`, 'transmutation', levels, { range: 'close', target: 'one creature/level', duration: '1 min./level', description: `As ${name.toLowerCase()}, affecting one creature/level (+4 enhancement to ${ability.toUpperCase()}).` }, buff(D.minutes(1), (cl, c, s) => [mod(ability, 4, 'enhancement', s)], { targets: 'allies' }));
const dispelAlignment = (name, against, descriptor, levels) => spell(name, 'abjuration', levels, { descriptors: [descriptor], range: 'touch', duration: '1 round/level or until discharged', description: `+4 deflection AC against ${against} creatures; can dismiss one ${against} outsider or dispel one ${against} spell.` }, buff(D.rounds(1), (cl, c, s) => [mod('ac', 4, 'deflection', s, [`vs${against[0].toUpperCase()}${against.slice(1)}`])]));
const symbol = (name, cond, levels, rounds, extra = {}) => spell(`Symbol of ${name}`, 'necromancy', levels, { castingTime: '10 minutes', range: '0 ft.', area: '60-ft.-radius spread', duration: 'see text', save: extra.saveText || 'Fortitude negates', description: `Triggered rune: creatures within 60 ft. are ${cond}.` }, condition(cond, rounds, { save: save(extra.save || 'fort'), area: { shape: 'burst', size: 60 } }));
const massInflict = (word, die, count, max, levels) => spell(`Mass Inflict ${word} Wounds`, 'necromancy', levels, { range: 'close', target: 'one creature/level', duration: 'instantaneous', save: 'Will half', description: `Deals ${count}d${die} + 1/level negative energy damage (max +${max}) to many creatures.` }, { ...inflict(die, count, max), attack: undefined, multiTarget: true });
const planarAlly = (name, levels, hd) => U(name, 'conjuration', levels, `Exchanges services with an outsider of up to ${hd} HD.`, { subschool: 'calling', castingTime: '10 minutes', range: 'close', duration: 'instantaneous', sr: false });
const planarBinding = (name, levels, hd) => U(name, 'conjuration', levels, `Traps an extraplanar creature of up to ${hd} HD until it performs a task.`, { subschool: 'calling', castingTime: '10 minutes', range: 'close', duration: 'instantaneous', save: 'Will negates' });

